def nCrMod(n, r, MOD):
    if r == 0 or r == n:
        return 1
    return ((n * nCrMod(n - 1, r - 1, MOD)) % MOD) * nCrMod(n - 1, r, MOD) % MOD

def solve(a, k):
    if len(a) == k:
        return 1
    ret = 0
    for i in range(1, k + 1):
        if k - i >= n - a[i - 1]:
            ret = (ret + pow(nCrMod(k - i + 1, n - a[i - 1] + 1, MOD), MOD - 2, MOD) * solve(a + [i], k - i) % MOD) % MOD
    return ret

