from collections import defaultdict
from typing import List

def reverse_substrings(s: str, t: str) -> List[List[int]]:
    # GFG solution: https://leetcode.com/problems/divide-array-into-subsequences/
    dp = [-1] * len(t)
    prev_end = -1
    for i in range(len(t) - 1, -1, -1):
        if dp[i] == -1:
            dp[i] = prev_end
        else:
            dp[i] = min(dp[i], prev_end)
        if s[i] == t[dp[i]]:
            dp[i] = i
        else:
            prev_end = dp[i]
    if dp[0] != -1:
        return dp[0]

    m, k = dp.count(-1), len(t) - 1
    t2, dp2 = t[:m + 1], []
    for i in range(m):  # Beginning of substrings
        t2, new_end = t[i + 1:], -1
        for j in range(i + 1, m * 2):
            if t2[j] == t2[j - m] == '1':
                new_end = j
                break
        if new_end != -1:
            dp2.append((i + 1, new_end + (not m % 2)))
            m //= 2
    res = dp2 + reversed(prev_end + 1)
    return shortest_splittable_subsequence_product([i + 1 for i, x in enumerate(res) if x > -1]) - 1 if res else None

def shortest_splittable_subsequence_product(lst) -> List[int]:
    if not lst:
        return -1
    for i in range(3):
        queue = [(lst[0], i, [i + 1])]
        p = lst.index(-1)
        q = [p]
        while not all(x > p for x in q):
            _, a, queue = queue.pop(0)
            if queue and queue[0][1] < a:
                break
            if a % 2 == a / b:
                queue.append((a * b, p, q + [a]))
            b = a % 2
    for i in range(3):
        res = min([b for (b, p, _) in queue], key=lambda x: (p - i, x)) + p
        if lst[res] == 1:
            return [
                res - 1 // 2 + (res % 2 and 1) + abs(i - 1),
                res // 2
            ]
            return res // 2

