            if l >= r:
                l, r = r, l
            ops.append((1, l, r, i))
            count2[i] = 0
        elif op[0] == 2:
            l, r = op[1] % n, (op[2] - 1) % n
            if l >= r:
                l, r = r, l
            count = accumulate(range(n), lambda next, _: next + count2[i])
            if count[l] == op[3]:
                count2[i] += 1
            else:
                count2[i] = 0

    for i, l, r, idx in ops:
        if i == idx:
            if 1 <= l <= r < n:
