import sys

def calculate_periods(length, string):
    # Get indices of unreadable characters
    unreadable_indices = [i for i, char in enumerate(string) if char == '?']
    # Get indices of possible valid characters
    valid_indices = [i for i, char in enumerate(string) if char != '?']

    periods = []
    if length > 1:
        # Find the smallest period involving just two characters
        for i in unreadable_indices:
            left, right = i, i
            while left - right > 1:
                left -= 1
                right -= 1
                if string[left] != string[right]:
                    break
            if left - right == -1:
                periods.extend([len(string)])
            else:
                periods.extend([left + 1, -right - 1])
        # Find the smallest period involving three characters
        for i in unreadable_indices:
            left, right = i, i
            while left - right > 2:
                left -= 2
                right -= 2
                if string[left] != string[right] and string[left - 1] != string[right + 1]:
                    break
            if left - right == -2:
                periods.extend([len(string)])
            else:
                periods.extend([left + 2, -right - 2])
    return sorted(set(periods))

