def max_union_area(n: int, rectangles: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict

    # Store the edge slopes of each rectangle in a dictionary
    edge_slopes = defaultdict(list)
    for x1, y1, a1 in rectangles:
        left_edge, right_edge = Fraction(y1 - x1), Fraction(x1 / y1)
        edge_slopes[left_edge].append((term1, term2))
        edge_slopes[right_edge].append((term1, term2))

    # Group rectangles by their edge slopes
    groups = {}
    for key in edge_slopes:
        for term1, term2 in edge_slopes[key]:
            if term1 not in groups:
                groups[term1] = []
            groups[term1].append(term2)

    # Merge groups with the highest numerators and denominators to maximize the union area
    while len(groups) > 1:
        larger = max(groups, key=len)
        smaller = min(groups.keys())

        if larger[1] > smaller[1]:
            remainder, new_top = groups[smaller], [z - smaller[1] for z in larger]
            if not remainder:
                continue
            for z in remainder:
                while new_top and new_top[-1] < z:
                    new_top.pop()
                if new_top:
                    new_top[-1] -= Fraction(z, new_top[-1])

        else:
            remainder, new_top = groups[larger], [z + larger[1] for z in larger[1]]
            if not remainder:
                continue
            for z in remainder:
                while new_top and new_top[-1] <= z + larger[1]:
                    new_top.pop()
                if new_top:
                    new_top[-1] += Fraction(z, new_top[-1])

        for new_term1, new_term2 in zip(larger[1], new_top):
            groups[new_term1].append((new_term2, new_term1, new_term2))

        for term1, term2 in groups[new_term1]:
            if term1 not in groups:
                groups[term1] = []
            groups[term1].append(term2)

    max_areas = 0
    for term1, term2 in groups[max(groups, key=lambda x: len(x) - x[0][1])] + groups[max(groups, key=lambda x: len(x) - x[0][1])[1]]:
        max_areas += term1

    return max_areas
