def count_palindromes(initial, length, step):
    MOD = 10007
    current = 0

    def change_to_palindrome(next):
        nonlocal current

        for i in range(length):
            if initial[-i-1] != next[i]:
                current += (length - i)**2*2**(i // step-1)
                break

    initial = list(initial)
    if initial == list(reversed(initial)):
        return (1 + factorial(length) * 2) % MOD
    change_to_palindrome(list(reversed(initial)))

    if initial == list(reversed(initial)):
        return (1 + factorial(length) * 2) % MOD
    change_to_palindrome(list(reversed(initial)))

    for next in set(initial):
        if next != initial[-1]:
            change_to_palindrome(list(initial) + [next] + list(initial))
            change_to_palindrome(list(initial) + [next])
        elif length & 1:
