                result += (len(set(text[k:k+i])) + 1) ** 2 % MOD
            else:
                for perm in permutations([m - 1 for m in range(1, 28)]):
                    if text[k+k:2*k+i] in set([p for p in permutations(text[k:2*k])]):
                        break
                    else:
                        result += len(set(text[k:k+i])) ** 2 % MOD
            if k + i == len(text) or text[k:k+i] != text[k+k+i:k+i] or text[k:k+i][0] == text[k+k+i][0] == text[k+k+i][1]:
                result += 1
    return result % MOD

