from functools import lru_cache
from math import gcd
from typing import Tuple

def lcm(x: int, y: int) -> int:
    return x * y // gcd(x, y)

LIMIT = 998244353

@lru_cache(None)
def extended_gcd(a: int, b: int) -> Tuple[int, int, int]:
    if b == 0:
        return a, 1, 0
    rev1, rev2, original_gcd = extended_gcd(b, a % b)
    return (original_gcd, rev2, rev1 - a // b * rev2)

def chinese_sums_equations(a: int, b: int) -> int:
    _, rev2, rev1 = extended_gcd(a, b)
    return a * rev2 % LIMIT

@lru_cache(None)
def catalan(n: int) -> int:
    if n == 0:
        return 1
    return sum(catalan(i) * catalan(n - i) for i in range(n)) * 2 // (n + 1)

def power(x: int, y: int, p: int) -> int:
    res = 1
    x = x % p
    while y > 0:
        if y & 1:
            res = res * x
            res %= p
        y = y >> 1
        x = x * x
        x %= p
    return res

def solve(n: int, k: int) -> int:
    return power(5, k, LIMIT) * (pow(2, n, LIMIT) - pow(2, n - 1, LIMIT) - 1) % LIMIT

