import sys

def max_hero_power(n, powers):
    prefix_sum = sorted(powers)
    memo = {}

    def max_hero(h, i):
        if h[0] in memo and h[1] in memo[h[0]]:
            return memo[h[0], h[1]]
        if i == n - 1:
            return h[0]
        max_val = h[1]
        if prefix_sum[i] <= h[0]:
            max_val = max(max_val, max_hero(h[0] + prefix_sum[i] * -2, i + 1))
        if i < n - 1 >= h[0]:
            max_val = max(max_val, max_hero(h[1] + prefix_sum[i + 1] * -2, i + 1))
        memo[h, i] = max_val
        return max_val

